import { PageModule } from "@stripe/ui-extension-sdk/ui";
import type { Member, ProgramConfig, Transaction } from "@/data";
import { FieldGrid } from "@/components/FieldGrid";
import { formatCurrency, formatPoints } from "@/utils/format";

type MemberDetailsModuleProps = {
  transaction: Transaction;
  member?: Member;
  currency?: ProgramConfig["currency"];
};

export function MemberDetailsModule({
  transaction,
  member,
  currency,
}: MemberDetailsModuleProps) {
  return (
    <PageModule title="Member">
      <FieldGrid>
        <FieldGrid.Field label="Email" value={transaction.memberEmail} />
        {member && <FieldGrid.Field label="Tier" value={member.tier} />}
        {member && (
          <FieldGrid.Field
            label="Current balance"
            value={`${formatPoints(member.points)} points`}
          />
        )}
        {member && (
          <FieldGrid.Field
            label="Lifetime spend"
            value={formatCurrency(member.lifetimeSpend, currency)}
          />
        )}
      </FieldGrid>
    </PageModule>
  );
}

import { useMemo } from "react";
import { useActivityQuery, useMembersQuery, useSettingsQuery } from "@/data";
import { formatPoints } from "@/utils/format";

export function useTransactionDetailPage(id: string) {
  const { data: activity, isFetching: activityLoading } = useActivityQuery();
  const { data: members, isFetching: membersLoading } = useMembersQuery();
  const { data: settings, isFetching: settingsLoading } = useSettingsQuery();

  const transaction = activity?.find((txn) => txn.id === id);
  const pending = activityLoading || membersLoading || settingsLoading;
  const notFound = !pending && !transaction;

  const member = useMemo(
    () => members?.find((m) => m.id === transaction?.memberId),
    [members, transaction?.memberId],
  );

  const pointsDisplay = transaction
    ? `${transaction.type === "earned" ? "+" : "-"}${formatPoints(transaction.points)}`
    : "";

  const typeLabel = transaction
    ? transaction.type === "earned"
      ? "Earned"
      : "Redeemed"
    : "";

  return {
    transaction,
    member,
    pending,
    notFound,
    settings,
    pointsDisplay,
    typeLabel,
  };
}

import { PageModule } from "@stripe/ui-extension-sdk/ui";
import type { Transaction } from "@/data";
import { StatCard } from "@/components/StatsCard";
import { formatTimestamp } from "@/utils/date";

type SummaryModuleProps = {
  transaction: Transaction;
  pointsDisplay: string;
  typeLabel: string;
};

export function SummaryModule({
  transaction,
  pointsDisplay,
  typeLabel,
}: SummaryModuleProps) {
  return (
    <PageModule title="Summary">
      <StatCard.Row>
        <StatCard label="Points" value={pointsDisplay} />
        <StatCard label="Type" value={typeLabel} />
