import Ajv from "ajv";
import addFormats from "ajv-formats";
import schema from "../stripe-app.schema.json";
import schemaLocal from "../stripe-app-local.schema.json";

const ajv = new Ajv();
addFormats(ajv);

// markdownDescription is not part of the JSON Schema standard, it's specific to VSCode
ajv.addKeyword("markdownDescription");

const validate = ajv.compile(schema);
const validateLocal = ajv.compile(schemaLocal);

const basicManifest = Object.freeze({
  id: "com.example.app",
  version: "0.0.1",
  name: "Test App",
  icon: "./icon.png",
  permissions: [
    {
      permission: "customer_read",
      purpose: "Cool purpose",
    },
  ],
  ui_extension: {
    views: [
      {
        viewport: "stripe.dashboard.customer.detail",
        component: "View",
      },
    ],
    actions: [],
    content_security_policy: {
      "connect-src": ["https://example.com/path"],
      purpose: "Test",
    },
  },
  post_install_action: {
    type: "settings",
  },
  constants: {
    HELLO: "world",
  },
  allowed_redirect_uris: [
    "https://myapp.com/cb",
    "https://localhost:3000/callback",
  ]
});

describe("Validate manifests", () => {
  it("validates a basic manifest", () => {
    const valid = validate(basicManifest);
    expect(valid).toBe(true);
  });

  it("validates a basic local manifest", () => {
    const valid = validateLocal({
      extends: "stripe-app.json",
      ...basicManifest,
    });
    expect(valid).toBe(true);
  });

  it("rejects an empty manifest", () => {
    const valid = validate({});
    expect(valid).toBe(false);
  });

  it("accepts an empty local manifest", () => {
    const valid = validateLocal({});
    expect(valid).toBe(true);
  });

  it("accepts underscores in app id", () => {
    const valid = validate({
      ...basicManifest,
      id: "app_id.stripe.com",
    });
    expect(valid).toBe(true);
  });

  it("rejects invalid permissions", () => {
    const valid = validate({
      ...basicManifest,
      permissions: [
        {
          permission: "fake_permission",
          purpose: "Cool purpose",
        },
      ],
    });
    expect(valid).toBe(false);
  });

  it("rejects invalid viewports", () => {
    const valid = validate({
      ...basicManifest,
      ui_extension: {
        ...basicManifest.ui_extension,
        views: [
          {
            viewport: "fake.viewport",
            component: "View",
          },
        ],
      },
    });
    expect(valid).toBe(false);
  });

  it("rejects CSP connect-src without a path", () => {
    const valid = validate({
      ...basicManifest,
      ui_extension: {
        ...basicManifest.ui_extension,
        content_security_policy: {
          "connect-src": ["https://no-path.com/"],
          purpose: "Test",
        },
      },
    });
    expect(valid).toBe(false);
  });

  it("rejects CSP connect-src without a purpose", () => {
    const valid = validate({
      ...basicManifest,
      ui_extension: {
        ...basicManifest.ui_extension,
        content_security_policy: {
          "connect-src":
            basicManifest.ui_extension.content_security_policy["connect-src"],
        },
      },
    });
    expect(valid).toBe(false);
  });

  it("accepts a local CSP connect-src without a purpose", () => {
    const valid = validateLocal({
      ui_extension: {
        content_security_policy: {
          "connect-src":
            basicManifest.ui_extension.content_security_policy["connect-src"],
        },
      },
    });
    expect(valid).toBe(true);
  });

  it("accepts post-install action url property for external", () => {
    const valid = validate({
      ...basicManifest,
      post_install_action: {
        type: "external",
        url: "https://example.com",
      },
    });
    expect(valid).toBe(true);
  });

  it("accepts post-install onboarding action", () => {
    const valid = validate({
      ...basicManifest,
      post_install_action: {
        type: "onboarding",
      },
    });
    expect(valid).toBe(true);
  });

  it("rejects post-install action url property for settings", () => {
    const valid = validate({
      ...basicManifest,
      post_install_action: {
        type: "settings",
        url: "https://example.com",
      },
    });
    expect(valid).toBe(false);
  });

  it("rejects post-install action url property for onboarding", () => {
    const valid = validate({
      ...basicManifest,
      post_install_action: {
        type: "onboarding",
        url: "https://example.com",
      },
    });
    expect(valid).toBe(false);
  });

  it("rejects invalid url property for allowed_redirect_uris", () => {
    const valid = validate({
      ...basicManifest,
      allowed_redirect_uris: ["invalid"]
    });
    expect(valid).toBe(false);
  });
});

import {
  activityData,
  membersData,
  membersTrend,
  pointsLiabilityTrend,
  redemptionsTrend,
  revenueTrend,
  rewardsData,
} from "./mock";
import { initialProgramConfig } from "./config";
import { queryKeys } from "./query-keys";

import type { QueryClient } from "@tanstack/react-query";
import type { Member, Reward, Transaction } from "./types";
import type { ProgramConfig } from "./config";

export function getOrSeedMembers(queryClient: QueryClient): Member[] {
  return queryClient.getQueryData<Member[]>(queryKeys.members) ?? [...membersData];
}

export function getOrSeedRewards(queryClient: QueryClient): Reward[] {
  return queryClient.getQueryData<Reward[]>(queryKeys.rewards) ?? [...rewardsData];
}

export function getOrSeedActivity(queryClient: QueryClient): Transaction[] {
  return (
    queryClient.getQueryData<Transaction[]>(queryKeys.activity) ?? [
      ...activityData,
    ]
  );
}

export function getOrSeedProgramConfig(queryClient: QueryClient): ProgramConfig {
  return (
    queryClient.getQueryData<ProgramConfig>(queryKeys.settings) ?? {
      ...initialProgramConfig,
    }
  );
}

export function syncCompositeQueries(queryClient: QueryClient) {
  const members = getOrSeedMembers(queryClient);
  const rewards = getOrSeedRewards(queryClient);
  const activity = getOrSeedActivity(queryClient);

  queryClient.setQueryData(queryKeys.members, members);
  queryClient.setQueryData(queryKeys.rewards, rewards);
  queryClient.setQueryData(queryKeys.activity, activity);

  queryClient.setQueryData(queryKeys.home, { members, rewards });
  queryClient.setQueryData(queryKeys.overview, {
    activity,
    membersTrend,
    revenueTrend,
    redemptionsTrend,
    pointsLiabilityTrend,
  });
  queryClient.setQueryData(queryKeys.memberDetail, { activity, rewards });
}

export function requireMembers(queryClient: QueryClient): Member[] {
  return getOrSeedMembers(queryClient);
}

export function requireRewards(queryClient: QueryClient): Reward[] {
  return getOrSeedRewards(queryClient);
}

export function requireActivity(queryClient: QueryClient): Transaction[] {
  return getOrSeedActivity(queryClient);
}

export function requireProgramConfig(queryClient: QueryClient): ProgramConfig {
  return getOrSeedProgramConfig(queryClient);
}

import type { QueryClient } from "@tanstack/react-query";

import type {
  GrantPointsInput,
  UpdateMemberInput,
  UpdateProgramConfigInput,
  UpdateRewardInput,
} from "./api";
import { queryKeys } from "./query-keys";
import {
  requireActivity,
  requireMembers,
  requireProgramConfig,
  requireRewards,
  syncCompositeQueries,
} from "./query-cache";

const GRANT_REASON_LABELS: Record<string, string> = {
  customer_service: "Customer service gesture",
  promotion: "Promotional campaign",
  referral: "Referral bonus",
  birthday: "Birthday reward",
  anniversary: "Membership anniversary",
  compensation: "Service recovery",
  other: "Other",
};

export function applyUpdateMember(
  queryClient: QueryClient,
  input: UpdateMemberInput,
) {
  const members = requireMembers(queryClient);
  if (!members.some((member) => member.id === input.id)) {
    throw new Error(`Member not found: ${input.id}`);
  }

  queryClient.setQueryData(
    queryKeys.members,
    members.map((member) =>
      member.id === input.id
        ? {
            ...member,
            name: input.name,
            email: input.email,
            lifetimeSpend: input.lifetimeSpend,
          }
        : member,
    ),
  );

  const activity = requireActivity(queryClient);
  queryClient.setQueryData(
    queryKeys.activity,
    activity.map((txn) =>
      txn.memberId === input.id
        ? { ...txn, memberName: input.name, memberEmail: input.email }
        : txn,
    ),
  );

  syncCompositeQueries(queryClient);
}

export function applyGrantPoints(
  queryClient: QueryClient,
  input: GrantPointsInput,
) {
  const members = requireMembers(queryClient);
  const member = members.find((m) => m.id === input.memberId);
  if (!member) {
    throw new Error(`Member not found: ${input.memberId}`);
  }
  if (input.points <= 0) {
    throw new Error("Points must be greater than zero");
  }

  queryClient.setQueryData(
    queryKeys.members,
    members.map((m) =>
      m.id === input.memberId
        ? { ...m, points: m.points + input.points }
        : m,
    ),
  );

  const description = input.reason
    ? (GRANT_REASON_LABELS[input.reason] ?? "Bonus points granted")
    : "Bonus points granted";

  const activity = requireActivity(queryClient);
  queryClient.setQueryData(queryKeys.activity, [
    {
      id: `txn_${Date.now()}`,
      memberId: member.id,
      memberName: member.name,
      memberEmail: member.email,
      type: "earned" as const,
      points: input.points,
      description,
      timestamp: new Date().toISOString(),
    },
    ...activity,
  ]);

  syncCompositeQueries(queryClient);
}

export function applyUpdateReward(
  queryClient: QueryClient,
  input: UpdateRewardInput,
) {
  const rewards = requireRewards(queryClient);
  const reward = rewards.find((r) => r.id === input.id);
  if (!reward) {
    throw new Error(`Reward not found: ${input.id}`);
  }

  const previousName = reward.name;
  queryClient.setQueryData(
    queryKeys.rewards,
    rewards.map((r) =>
      r.id === input.id
        ? {
            ...r,
            name: input.name,
            description: input.description,
            pointsCost: input.pointsCost,
            category: input.category,
            available: input.available,
          }
        : r,
    ),
  );

  if (input.name !== previousName) {
    const activity = requireActivity(queryClient);
    queryClient.setQueryData(
      queryKeys.activity,
      activity.map((txn) =>
        txn.type === "redeemed" && txn.description === previousName
          ? { ...txn, description: input.name }
          : txn,
      ),
    );
  }

  syncCompositeQueries(queryClient);
}

export function applyArchiveReward(queryClient: QueryClient, id: string) {
  applyArchiveRewards(queryClient, [id]);
}

export function applyArchiveRewards(queryClient: QueryClient, ids: string[]) {
  const rewards = requireRewards(queryClient);
  const idSet = new Set(ids);
  if (!ids.every((id) => rewards.some((reward) => reward.id === id))) {
    throw new Error("One or more rewards were not found");
  }

  queryClient.setQueryData(
    queryKeys.rewards,
    rewards.map((reward) =>
      idSet.has(reward.id) ? { ...reward, available: false } : reward,
    ),
  );

  syncCompositeQueries(queryClient);
}

export function applyUpdateProgramConfig(
  queryClient: QueryClient,
  input: UpdateProgramConfigInput,
) {
  const current = requireProgramConfig(queryClient);
  queryClient.setQueryData(queryKeys.settings, {
    ...current,
    name: input.name,
    pointsPerDollar: input.pointsPerDollar,
    currency: input.currency,
    engagementWindows: {
      ...current.engagementWindows,
      active: input.engagementWindows.active,
      atRisk: input.engagementWindows.atRisk,
    },
  });
}

